import urllib.request, re
url='https://www.imf.org/external/pubs/ft/weo/2025/02/weodata/weoselgr.aspx'
html=urllib.request.urlopen(url).read().decode('utf-8')
# find form action
m=re.search(r'<form[^>]+action="([^"]+)"', html, re.I)
print('form action', m.group(1) if m else None)
# find any mention of weorept
for pat in ['weorept','weodata','weoindex']:
    if pat in html:
        print('found', pat)
print('action lines with weorept:')
for line in html.split('\n'):
    if 'weorept' in line.lower():
        print(line.strip()[:200])
