import json, urllib.request

def fetch(series):
    url=f'https://api.db.nomics.world/v22/series/IMF/WEO:latest/{series}?observations=1'
    data=json.loads(urllib.request.urlopen(url).read().decode('utf-8'))
    print(series, 'dataset', data['series']['dataset_code'], 'freq', data['series']['frequency'])
    print('last obs', data['series']['observations'][-1])

for s in ['GEO.NGDP_RPCH','GEO.NGDP_R','GEO.NGDP_D','GEO.NGDPD','GEO.NGDP_XDC']:
    try:
        fetch(s)
    except Exception as e:
        print(s, 'error', e)
